def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a 2D list to store the grid values
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Create a 4D DP array to store the maximum sum of values collected on two paths
    dp = [[[[0] * N for _ in range(N)] for _ in range(N)] for _ in range(N)]

    # Initialize the starting point
    dp[0][0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(N):
                for l in range(N):
                    if i == 0 and j == 0 and k == 0 and l == 0:
                        continue
                    if i > 0:
                        dp[i][j][k][l] = max(dp[i][j][k][l], dp[i-1][j][k][l] + grid[i][j])
                    if j > 0:
                        dp[i][j][k][l] = max(dp[i][j][k][l], dp[i][j-1][k][l] + grid[i][j])
                    if k > 0:
                        dp[i][j][k][l] = max(dp[i][j][k][l], dp[i][j][k-1][l] + grid[k][l])
                    if l > 0:
                        dp[i][j][k][l] = max(dp[i][j][k][l], dp[i][j][k][l-1] + grid[k][l])

    # The maximum sum of values collected on the two paths is stored in dp[N-1][N-1][N-1][N-1]
    return dp[N-1][N-1][N-1][N-1]

