def cantor_numbering(N: int) -> str:
    """
    Determines the numerator and denominator of the N-th term in the Cantor table.

    Args:
    - N (int): The position in the Cantor table to find the corresponding fraction for.

    Returns:
    - str: A string representation of the fraction at the N-th position in the Cantor table.
    """
    if N == 1:
        return "1/1"

    row = 0
    col = 0
    count = 0
    direction = 1  # 1 for up-left, -1 for down-right

    while count < N:
        if direction == 1:
            for _ in range(row + col + 1):
                count += 1
                if count == N:
                    return f"{col + 1}/{row + col + 1 - col}"
            col += 1
            direction = -1
        else:
            for _ in range(row + col + 1):
                count += 1
                if count == N:
                    return f"{col + 1}/{row + col + 1 - col}"
            row += 1
            direction = 1

    return "N is out of bounds for the Cantor table"

