def count_passing_ways(n: int, m: int) -> int:
    MOD = 10**9 + 7

    # Initialize a 2D dp array
    dp = [[0] * (m + 1) for _ in range(n)]

    # Base cases
    for i in range(n):
        dp[i][0] = 1  # One way to be at the same position after 0 passes

    # Fill the dp table
    for k in range(1, m + 1):
        for i in range(n):
            dp[i][k] = (dp[(i - 1 + n) % n][k - 1] + dp[(i + 1) % n][k - 1]) % MOD

    # The result is the number of ways to be at the starting position after m passes
    return dp[0][m]

